// Ambient types for the build-time generated module (dist/generated.js),
// emitted by scripts/build-site.ts and inlined into the Worker by Wrangler.
declare module '*/generated.js' {
  export const HOME_HTML: string;
  export const DOCS_HTML: string;
  export const NOT_FOUND_HTML: string;
  export const STYLES_CSS: string;
  export const SCRIPTS_JS: string;
}
